"use client"

import { useState } from "react"

import { storyMedia } from "../media-assets"
import { downloadMedia } from "../media-context-menu"
import { ClipsHeader, ClipsLibrary, type Clip } from "./clips-components"
import type { PlannerPageContent } from "@/sanity/lib/planner-pages"

const initialFootage: Clip[] = [
  {
    id: 3,
    name: "salt-flats-wind-test-04.mp4",
    duration: "0:18",
    uploaded: "Today, 3:08 PM",
    imageUrl: storyMedia.saltSignal.wide,
  },
  {
    id: 2,
    name: "lighthouse-weather-reference.mov",
    duration: "0:12",
    uploaded: "Yesterday",
    imageUrl: storyMedia.blackTide.wide,
  },
  {
    id: 1,
    name: "pool-rehearsal-wide.mp4",
    duration: "0:24",
    uploaded: "Jul 21",
    imageUrl: storyMedia.afterHours.wide,
  },
]

export function FootageWorkspace({ content }: { content: PlannerPageContent }) {
  const [footage, setFootage] = useState(initialFootage)
  function addFootage(files: FileList | null) {
    if (!files?.length) return
    const additions = Array.from(files)
      .filter((file) => file.type.startsWith("video/"))
      .map((file, index) => ({
        id: (footage[0]?.id ?? 0) + index + 1,
        name: file.name,
        duration: "0:00",
        uploaded: "Just now",
        imageUrl: storyMedia.saltSignal.wide,
      }))
    setFootage((current) => [...additions.reverse(), ...current])
  }
  return (
    <main className="flex h-[calc(100dvh-4rem)] flex-col overflow-hidden md:h-dvh">
      <section className="min-h-0 flex-1 overflow-y-auto overscroll-none">
        <div className="mx-auto max-w-6xl px-4 pb-10 sm:px-6">
          <ClipsHeader
            title={content.heading!}
            actionLabel={content.primaryActionLabel!}
            onUpload={addFootage}
          />
          <ClipsLibrary
            clips={footage}
            emptyStateTitle={content.emptyStateTitle!}
            onDownload={(clip) => downloadMedia(clip.imageUrl, clip.name)}
            onDuplicate={(clip) =>
              setFootage((current) => [
                {
                  ...clip,
                  id: Math.max(...current.map((entry) => entry.id)) + 1,
                  name: `Copy of ${clip.name}`,
                  uploaded: "Just now",
                },
                ...current,
              ])
            }
            onRemove={(clip) =>
              setFootage((current) =>
                current.filter((entry) => entry.id !== clip.id)
              )
            }
          />
        </div>
      </section>
    </main>
  )
}

const assetRoot = "/generated/2026-07-24-004043"
const slugGangAssetRoot = "/generated/2026-07-24-142500-slug-gang"

export const storyMedia = {
  saltSignal: {
    wide: `${assetRoot}/salt-signal-wide.webp`,
    character: `${assetRoot}/mara-portrait.webp`,
  },
  blackTide: {
    wide: `${assetRoot}/black-tide-wide.webp`,
    character: `${assetRoot}/june-portrait.webp`,
  },
  afterHours: {
    wide: `${assetRoot}/after-hours-wide.webp`,
    character: `${assetRoot}/eli-portrait.webp`,
  },
} as const

export const storyboardFrames = {
  slugGang: [
    `${slugGangAssetRoot}/scene-01.png`,
    `${slugGangAssetRoot}/scene-02.png`,
    `${slugGangAssetRoot}/scene-03.png`,
    `${slugGangAssetRoot}/scene-04.png`,
    `${slugGangAssetRoot}/scene-05.png`,
    `${slugGangAssetRoot}/scene-06.png`,
    `${slugGangAssetRoot}/scene-07.png`,
    `${slugGangAssetRoot}/scene-08.png`,
  ],
  saltSignal: [
    storyMedia.saltSignal.wide,
    storyMedia.saltSignal.character,
    storyMedia.saltSignal.wide,
    storyMedia.saltSignal.wide,
  ],
  blackTide: [
    storyMedia.blackTide.wide,
    storyMedia.blackTide.character,
    storyMedia.blackTide.wide,
    storyMedia.blackTide.character,
  ],
  afterHours: [
    storyMedia.afterHours.wide,
    storyMedia.afterHours.character,
    storyMedia.afterHours.wide,
    storyMedia.afterHours.character,
  ],
} as const

export function frameAt(frames: readonly string[], index: number) {
  return frames[index % frames.length]
}

export function framesForName(name: string) {
  const normalized = name.toLowerCase()
  if (normalized.includes("tide") || normalized.includes("june")) {
    return storyboardFrames.blackTide
  }
  if (
    normalized.includes("after") ||
    normalized.includes("rehearsal") ||
    normalized.includes("eli")
  ) {
    return storyboardFrames.afterHours
  }
  return storyboardFrames.saltSignal
}

"use client"

import type { ComponentProps, ReactNode } from "react"
import {
  ArrowDownToLineIcon,
  CopyIcon,
  ExternalLinkIcon,
  RotateCwIcon,
  Trash2Icon,
} from "lucide-react"

import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuSeparator,
  ContextMenuTrigger,
} from "@/components/ui/context-menu"
import { cn } from "@/lib/utils"

type MediaContextMenuProps = {
  children: ReactNode
  className?: string
  triggerProps?: Omit<ComponentProps<"div">, "children" | "className">
  onOpen?: () => void
  openLabel?: string
  onDownload?: () => void
  onDuplicate?: () => void
  duplicateLabel?: string
  onRemove?: () => void
  removeLabel?: string
}

export function MediaContextMenu({
  children,
  className,
  triggerProps,
  onOpen,
  openLabel = "Open",
  onDownload,
  onDuplicate,
  duplicateLabel = "Duplicate",
  onRemove,
  removeLabel = "Remove",
}: MediaContextMenuProps) {
  return (
    <ContextMenu>
      <ContextMenuTrigger
        className={cn("min-w-0", className)}
        {...triggerProps}
      >
        {children}
      </ContextMenuTrigger>
      <ContextMenuContent>
        {onOpen && (
          <ContextMenuItem onClick={onOpen}>
            <ExternalLinkIcon />
            {openLabel}
          </ContextMenuItem>
        )}
        {onDownload && (
          <ContextMenuItem onClick={onDownload}>
            <ArrowDownToLineIcon />
            Download
          </ContextMenuItem>
        )}
        {onDuplicate && (
          <ContextMenuItem onClick={onDuplicate}>
            {duplicateLabel.toLowerCase().includes("reroll") ? (
              <RotateCwIcon />
            ) : (
              <CopyIcon />
            )}
            {duplicateLabel}
          </ContextMenuItem>
        )}
        {onRemove && (
          <>
            <ContextMenuSeparator />
            <ContextMenuItem variant="destructive" onClick={onRemove}>
              <Trash2Icon />
              {removeLabel}
            </ContextMenuItem>
          </>
        )}
      </ContextMenuContent>
    </ContextMenu>
  )
}

export function downloadMedia(url: string, filename: string) {
  const anchor = document.createElement("a")
  anchor.href = url
  anchor.download = filename
  anchor.click()
}

"use client"
import { useRef } from "react"
import { PlusIcon } from "lucide-react"
import { Button } from "@/components/ui/button"
export function ClipsHeader({
  title,
  actionLabel,
  onUpload,
}: {
  title: string
  actionLabel: string
  onUpload: (files: FileList | null) => void
}) {
  const uploadRef = useRef<HTMLInputElement>(null)
  return (
    <header className="flex items-center justify-between gap-4 py-4">
      <h1 className="text-xl font-medium">{title}</h1>
      <Button className="h-10 px-5" onClick={() => uploadRef.current?.click()}>
        <PlusIcon className="size-6" />
        {actionLabel}
      </Button>
      <input
        ref={uploadRef}
        type="file"
        accept="video/*"
        multiple
        className="sr-only"
        onChange={(event) => onUpload(event.target.files)}
      />
    </header>
  )
}

import { FilmIcon } from "lucide-react"
import { ClientEmptyState } from "./client-empty-state"
import { ClipCard } from "./clip-card"
import type { ClientClip } from "./client-clip"
export function ClipsLibrary({
  clips,
  emptyStateTitle,
  onDownload,
  onDuplicate,
  onRemove,
}: {
  clips: ClientClip[]
  emptyStateTitle: string
  onDownload: (clip: ClientClip) => void
  onDuplicate: (clip: ClientClip) => void
  onRemove: (clip: ClientClip) => void
}) {
  if (!clips.length)
    return <ClientEmptyState icon={FilmIcon} title={emptyStateTitle} />
  return (
    <div className="space-y-2 py-6">
      {clips.map((clip) => (
        <ClipCard
          key={clip.id}
          clip={clip}
          onDownload={() => onDownload(clip)}
          onDuplicate={() => onDuplicate(clip)}
          onRemove={() => onRemove(clip)}
        />
      ))}
    </div>
  )
}

import { createClient } from "next-sanity"

import { apiVersion, dataset, projectId } from "@/sanity/env"

export const sanityClient = createClient({
  projectId,
  dataset,
  apiVersion,
  useCdn: true,
  stega: {
    studioUrl: "/studio",
  },
})

import type { LucideIcon } from "lucide-react"

export function ClientEmptyState({ icon: Icon, title, description }: { icon: LucideIcon; title: string; description?: string }) {
  return (
    <div className="flex min-h-80 flex-col items-center justify-center text-center">
      <Icon className="size-5 text-muted-foreground" aria-hidden="true" />
      <p className="mt-3 text-sm font-medium">{title}</p>
      {description ? <p className="mt-1 max-w-sm text-sm text-muted-foreground">{description}</p> : null}
    </div>
  )
}

const requiredEnv = (name: string, value: string | undefined) => {
  if (!value) {
    throw new Error(`Missing ${name}`)
  }

  return value
}

const projectId = requiredEnv(
  "NEXT_PUBLIC_SANITY_PROJECT_ID",
  process.env.NEXT_PUBLIC_SANITY_PROJECT_ID
)
const dataset = requiredEnv(
  "NEXT_PUBLIC_SANITY_DATASET",
  process.env.NEXT_PUBLIC_SANITY_DATASET
)
const apiVersion =
  process.env.NEXT_PUBLIC_SANITY_API_VERSION || "2026-07-26"

export { apiVersion, dataset, projectId }
